exercises.solution:
import math

def fragments(taille, mtu):
    return math.ceil(taille / mtu)

def encapsuler(message, port, ip_src, ip_dst):
    segment = {"port_destination": port, "donnees": message}
    return {"ip_source": ip_src, "ip_destination": ip_dst, "ttl": 64, "donnees": segment}

