exercises.solution:
def resume(trame):
    try:
        paquet = trame["donnees"]
        segment = paquet["donnees"]
        return {"de": paquet["ip_source"], "vers": paquet["ip_destination"], "port": segment["port_destination"], "message": segment["donnees"]}
    except KeyError:
        raise ValueError("trame incomplète")
